    await page.getByRole("button", { name: "Add To Cart" }).click();
    await page.locator("#zip_code").fill("abcde");
    await page.getByRole("button", { name: "Next: Payment →" }).click();
    await page.getByRole("button", { name: "Next: Review →" }).click();
    await page.locator("#place-order-btn").click();

    // Submission was blocked: still on /cart, still stuck on the Review step.
    await expect(page).toHaveURL(`${baseUrl}/cart`);
    await expect(page.locator("#checkout-step-3")).toHaveClass(/active/);

    // EXPECTED-FAIL: documents a real bug. The invalid zip sits in the collapsed
